import'package:cloud_firestore/cloud_firestore.dart';import'package:firebase_auth/firebase_auth.dart';import'../models/learner_twin.dart';class FunziData{static final db=FirebaseFirestore.instance;static String get uid=>FirebaseAuth.instance.currentUser!.uid;static Future<LearnerTwin?> twin()async{final s=await db.collection('learnerTwins').doc(uid).get();return s.exists?LearnerTwin.fromMap(s.data()!):null;}static Stream<QuerySnapshot<Map<String,dynamic>>> leaderboard()=>db.collection('leaderboard').orderBy('improvementScore',descending:true).limit(20).snapshots();static Stream<QuerySnapshot<Map<String,dynamic>>> portfolio()=>db.collection('portfolios').doc(uid).collection('evidence').orderBy('createdAt',descending:true).snapshots();static Future<List<String>> linkedLearners()async{final q=await db.collection('parentLinks').where('parentId',isEqualTo:uid).where('status',isEqualTo:'active').get();return q.docs.map((d)=>"${d.data()['learnerId']}").toList();}}